  function pickedStone(room) {
    let all = room.stones || [[room.stone, 1]],
      sum = all.reduce((n, r) => n + r[1], 0),
      v = Math.random() * sum;
    for (let [lvl, weight] of all) {
      v -= weight;
      if (v < 0) return lvl;
    }
    return all[all.length - 1][0];
  }
