  function exportData() {
    saveGame();
    return JSONcopy({ ...roster, bindings, exportedAt: new Date().toISOString() });
  }
  function downloadBackup() {
    let blob = new Blob([JSON.stringify(exportData(), null, 2)], { type: 'application/json' }),
      url = URL.createObjectURL(blob),
      a = document.createElement('a');
    a.href = url;
    a.download = 'joan-postavy-' + new Date().toISOString().slice(0, 10) + '.json';
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1500);
    notify('Záloha všech postav připravena.');
  }

  function clearInputs() {
    for (let k in keys) keys[k] = false;
    mouse.down = false;
  }
  function keyLabel(code) {
    return code
      .replace('Digit', '')
      .replace('Key', '')
      .replace('ShiftLeft', 'Levý Shift')
      .replace('ShiftRight', 'Pravý Shift')
      .replace('Space', 'Mezerník')
      .replace('ArrowUp', '↑')
      .replace('ArrowDown', '↓')
      .replace('ArrowLeft', '←')
      .replace('ArrowRight', '→');
  }
  function showBindings() {
    openChoice(
      'Ovládání',
      'Používáme fyzickou polohu kláves: horní řada 1–6 funguje i jako + ě š č ř ž. Výchozí schopnosti fungují také na Z X C V B N. Klikni na bind a stiskni novou klávesu.',
    );
    let names = {
      up: 'Nahoru',
      down: 'Dolů',
      left: 'Doleva',
      right: 'Doprava',
      attack: 'Útok',
      red: 'HP lektvar',
      blue: 'MP lektvar',
      dash: 'Úskok',
      interact: 'Interakce',
      mount: 'Kůň / sesednout',
      sage: 'Sage kouzlo',
    };
    for (let [action, code] of Object.entries(bindings)) {
      let row = document.createElement('div');
      row.className = 'binding-row';
      let label = document.createElement('span');
      label.textContent = names[action] || 'Schopnost ' + (Number(action.slice(-1)) + 1);
      let b = document.createElement('button');
      b.className = 'action alt';
      b.textContent = keyLabel(code);
      b.onclick = () => {
        captureBind = action;
        document.querySelectorAll('.binding-row').forEach((r) => r.classList.remove('waiting'));
        row.classList.add('waiting');
        b.textContent = 'Stiskni klávesu…';
      };
      row.append(label, b);
      $('choiceBody').appendChild(row);
    }
    let reset = document.createElement('button');
    reset.className = 'action';
    reset.textContent = 'Obnovit výchozí';
    reset.onclick = () => {
      bindings = { ...DEFAULT_BINDS };
      saveRoster();
      showBindings();
      if (player) renderSkills();
    };
    $('choiceBody').appendChild(reset);
  }
  function handleKeyV27(e, down) {
    if (captureBind && down) {
      e.preventDefault();
      if (e.code === 'Escape') {
        captureBind = null;
        showBindings();
        return;
      }
      if (
        !/^(Key[A-Z]|Digit[0-9]|F[1-9]|F1[0-2]|Space|ShiftLeft|ShiftRight|ControlLeft|ControlRight|AltLeft|AltRight|ArrowUp|ArrowDown|ArrowLeft|ArrowRight|Tab|Enter|Backspace|Numpad[0-9])$/.test(
          e.code,
        )
      )
        return;
      let collision = Object.keys(bindings).find((k) => bindings[k] === e.code && k !== captureBind);
      if (collision) {
        let old = bindings[captureBind];
        bindings[collision] = old;
      }
      bindings[captureBind] = e.code;
      captureBind = null;
      clearInputs();
      saveRoster();
      showBindings();
      if (player) renderSkills();
      return;
    }
    if (e.target?.closest?.('summary') && ['Space', 'Enter'].includes(e.code)) {
      if (!down) keys[' '] = false;
      return;
    }
    let guide = document.querySelectorAll('.guide-menu')[0];
    if (down && e.code === 'Escape' && !e.repeat && guide?.open) {
      guide.open = false;
      e.preventDefault();
      return;
    }
    if (e.target?.closest?.('input,textarea,select')) return;
    if (e.code === 'Escape' && down && !e.repeat) {
      e.preventDefault();
      if (!$('choiceModal').classList.contains('hidden')) closeChoice();
      else if (!$('creation').classList.contains('hidden') && player) {
        $('creation').classList.add('hidden');
        paused = false;
        clearInputs();
      } else openRoster();
      return;
    }
    if (!player || paused) return;
    let action = Object.keys(bindings).find((k) => bindings[k] === e.code),
      arrows = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right' };
    action = action || arrows[e.code];
    if (!action) {
      let j = ['KeyZ', 'KeyX', 'KeyC', 'KeyV', 'KeyB', 'KeyN'].indexOf(e.code);
      if (j >= 0 && bindings['skill' + j] === DEFAULT_BINDS['skill' + j]) action = 'skill' + j;
    }
    if (!action) return;
    e.preventDefault();
    let movement = { up: 'w', down: 's', left: 'a', right: 'd', attack: ' ' };
    if (movement[action]) {
      keys[movement[action]] = down;
      return;
    }
    if (!down || (e.repeat && !['red', 'blue'].includes(action))) return;
    activityAt = time;
    if (action.startsWith('skill')) useSkill(Number(action.slice(-1)));
    else if (action === 'red' || action === 'blue') usePotion(action);
    else if (action === 'dash') dash();
    else if (action === 'mount') toggleMount();
    else if (action === 'interact') interact();
    else if (action === 'sage') v111UseSage();
  }
  function setupExtendedUIV20() {
    window.addEventListener('keydown', (e) => handleKey(e, true));
    window.addEventListener('keyup', (e) => handleKey(e, false));
    window.addEventListener('blur', clearInputs);
    document.addEventListener('visibilitychange', () => {
      clearInputs();
      if (document.hidden) saveGame();
    });
    $('btnNew').onclick = openRoster;
    $('btnSave').onclick = () => {
      if (saveGame()) notify('Postava uložena.');
    };
    $('btnBindings').onclick = showBindings;
    $('btnSkills').onclick = () => showSkills();
    $('btnResume').onclick = () => {
      $('creation').classList.add('hidden');
      paused = false;
      clearInputs();
    };
    $('choiceClose').onclick = closeChoice;
    $('btnExport').onclick = downloadBackup;
    $('btnImport').onclick = () => $('importFile').click();
    $('importFile').onchange = async (e) => {
      let f = e.target.files[0];
      if (!f) return;
      try {
        if (f.size > 10 * 1024 * 1024) throw new Error('Záloha je příliš velká.');
        let n = importData(JSON.parse(await f.text()));
        notify('Importováno ' + n + ' postav. Stávající postavy zůstaly zachované.');
      } catch (err) {
        notify(err.message);
      }
      e.target.value = '';
    };
  }

  function recordContract(kind, m) {
    let a = player?.contract;
    if (!a || a.room !== current) return;
    if (kind === 'stone') a.stones++;
    else {
      a.kills++;
      if (TYPES[m.type]?.boss) a.boss++;
    }
  }
  function contractDone() {
    let a = player?.contract,
      c = a && contractFor(a.room);
    return !!(c && a.kills >= c.kills && a.stones >= c.stones && a.boss >= c.boss);
  }
  function claimContract() {
    if (!contractDone()) return;
    let a = player.contract,
      c = contractFor(a.room),
      repeat = player.contractClears[a.room] || 0,
      scale = repeat ? 0.6 : 1,
      n = Math.round(c.xp * scale),
      yang = Math.round(c.gold * scale);
    player.contractClears[a.room] = repeat + 1;
    player.contract = null;
    player.gold += yang;
    addExp(n);
    notify('Quest · +' + Math.round(n * BALANCE.xp) + ' EXP · +' + yang + ' Yang');
    refreshUI();
    saveGame();
  }
  function refreshContract() {
    if (!player) return;
    let wrap = $('contract'),
      a = player.contract,
      c = a && contractFor(a.room);
    wrap.innerHTML = '';
    $('contractCount').textContent = Object.values(player.contractClears).reduce((x, n) => x + n, 0) + ' splněno';
    if (c) {
      let repeat = player.contractClears[a.room] || 0,
        sc = repeat ? 0.6 : 1,
        sum = Math.min(a.kills, c.kills) + Math.min(a.stones, c.stones) + Math.min(a.boss, c.boss),
        total = c.kills + c.stones + c.boss;
      wrap.innerHTML =
        '<div class="contract-title">' +
        esc(c.name) +
        ' · ' +
        mapCode(a.room) +
        '</div><div class="contract-desc">Postup trvá přes více automatických respawnů.</div><div class="progress-track"><i style="width:' +
        Math.round((100 * sum) / total) +
        '%"></i></div><div>Nepřátelé: ' +
        Math.min(a.kills, c.kills) +
        ' / ' +
        c.kills +
        ' · Metiny: ' +
        Math.min(a.stones, c.stones) +
        ' / ' +
        c.stones +
        (c.boss ? ' · Boss: ' + Math.min(a.boss, c.boss) + ' / ' + c.boss : '') +
        '</div><div>Odměna: ' +
        fmt(Math.round(c.xp * sc * BALANCE.xp)) +
        ' EXP · ' +
        fmtY(Math.round(c.gold * sc)) +
        ' Yang</div>';
      let b = document.createElement('button');
      b.className = 'claim';
      b.textContent = contractDone() ? 'Vyzvednout odměnu' : 'Quest probíhá';
      b.disabled = !contractDone();
      b.onclick = claimContract;
      wrap.appendChild(b);
      b = document.createElement('button');
      b.className = 'action alt';
      b.textContent = 'Změnit quest';
      b.onclick = () => {
        if (confirm('Zahodit postup questu?')) {
          player.contract = null;
          refreshUI();
          saveGame();
        }
      };
      wrap.appendChild(b);
    } else {
      let list = document.createElement('div');
      list.className = 'contract-list';
      for (let q of CONTRACTS.filter((c) => !isTown(c.room) && regionOf(c.room) === regionView)) {
        let b = document.createElement('button');
        b.disabled = false;
        b.innerHTML = '<b>' + mapCode(q.room) + '</b>' + esc(q.name);
        b.onclick = () => acceptContract(q.room);
        list.appendChild(b);
      }
      wrap.appendChild(list);
    }
    let rate = (expSamples.reduce((n, v) => n + v.n, 0) / Math.min(Math.max(time, 60), 300)) * 60;
    $('runMeta').innerHTML =
      '<div>Odehráno: <b>' +
      timeText(player.playTime) +
      '</b> · ' +
      fmt(player.xpEarned) +
      ' EXP</div><div>Lov: ' +
      fmt(player.kills) +
      ' · Metiny: ' +
      player.metins +
      ' · Bossové: ' +
      player.bossKills +
      '</div><div>Posledních 5 min: ' +
      fmt(rate) +
      ' EXP/min</div><div>Nová EXP křivka brzdí rychlé plošné farmení. Vyšší moby nyní dávají výrazně více EXP; slabé příšery mají další postih.</div>';
  }
  function itemIconBase(it) {
    let slot = it.slot || it,
      body = '';
    let col = '#d9c78b',
      metal = '#cdded9';
    if (slot === 'weapon') {
      if (it.weaponSchool === 'archer')
        body =
          '<path d="M11 4 Q34 20 11 36 L17 20 Z" fill="#bc8c50"/><path d="M11 4 L11 36" stroke="#e9d8aa"/><path d="M5 20h29m-5-4 5 4-5 4" stroke="#d4ded7"/>';
      else if (it.weaponClass === 'shaman')
        body = '<path d="M8 8 Q20 0 32 8 L21 30 Z" fill="#c890a0"/><path d="M8 8 21 30 32 8M20 5v28" stroke="#e5cf88"/>';
      else if (it.weaponClass === 'lycan') body = '<path d="M10 30 8 7 13 22 17 5 19 22 25 6 24 31 Z" fill="#cdded9"/>';
      else body = '<path d="M12 29 26 7 31 4 31 10 18 33 Z" fill="#cdded9"/><path d="m10 26 13 9m-6-4-5 7" stroke="#d9b765" stroke-width="4"/>';
    } else if (slot === 'armor')
      body = '<path d="m11 6-7 9 5 4 4-3v19h17V16l4 3 4-4-8-9-8 4Z" fill="#899ca6"/><path d="M16 12v17m10-17v17M13 28h17" stroke="#ead69b"/>';
    else if (slot === 'helmet')
      body = '<path d="M6 28V17 Q20-2 34 17v11H6Z" fill="#a0b3b5"/><path d="M20 7v25M5 28h30" stroke="#d8bc6e" stroke-width="3"/>';
    else if (slot === 'shield')
      body = '<path d="M7 7h26v16L20 36 7 23Z" fill="#9a7961" stroke="#e3c788"/><path d="M20 9v22M11 20h18" stroke="#b9ccbe" stroke-width="3"/>';
    else if (slot === 'boots')
      body = '<path d="M12 5h14v17l9 7v6H9V24Z" fill="#99765a" stroke="#e3cc9c"/><path d="M12 13h13M12 18h13" stroke="#d0b371"/>';
    else if (slot === 'earrings')
      body =
        '<circle cx="12" cy="14" r="7" fill="none" stroke="#e8c975" stroke-width="4"/><circle cx="28" cy="21" r="7" fill="none" stroke="#e8c975" stroke-width="4"/><path d="m12 22-5 9h10Z" fill="#93bda9"/>';
    else if (slot === 'bracelet')
      body = '<ellipse cx="20" cy="21" rx="13" ry="10" fill="none" stroke="#e2c987" stroke-width="6"/><path d="m20 6 7 10-7 8-7-8Z" fill="#94c6ac"/>';
    else body = '<path d="M7 6 Q20 34 33 6" fill="none" stroke="#e1c276" stroke-width="3"/><path d="m20 23 7 7-7 8-7-8Z" fill="#a2b6da"/>';
    return '<svg viewBox="0 0 40 40" aria-hidden="true">' + body + '</svg>';
  }
  function refreshBaseUI() {
    if (!player) return;
    renderStats();
    let eq = $('equipment');
    eq.innerHTML = '';
    for (let [slot, [name, ico]] of Object.entries(SLOT)) {
      let it = equipped[slot],
        b = document.createElement('button');
      b.className = 'slot ' + (it ? 'equipped' : '');
      b.title = it ? itemTitle(it) + ' · kliknutím sundat' : name;
      b.innerHTML = '<b>' + (it ? itemIcon(it) : ico) + (it ? ' +' + it.plus : '') + '</b><small>' + name + '</small>';
      b.onclick = () => unequip(slot);
      eq.appendChild(b);
    }
    let inv = $('inventory');
    inv.innerHTML = '';
    for (let [i, it] of inventory.entries()) {
      let b = document.createElement('button');
      b.className = 'item ' + RARITIES[it.rarity].cls + (selectedItem === i ? ' pick' : '');
      b.title = itemTitle(it);
      b.innerHTML = '<strong>' + itemIcon(it) + '</strong><span>' + esc(itemTitle(it)) + '</span>';
      b.onclick = () => {
        selectedItem = i;
        refreshUI();
      };
      inv.appendChild(b);
    }
    if (!inventory.length) inv.innerHTML = '<div class="empty">Batoh je prázdný.</div>';
    $('invCount').textContent = inventory.length + ' / ' + bagCapacity();
    let it = inventory[selectedItem],
      detail = $('itemDetail'),
      acts = $('itemActions');
    acts.innerHTML = '';
    if (it) {
      let r = RARITIES[it.rarity],
        price = Math.round(45 * Math.pow(it.plus + 1, 1.8) * (1 + it.level * 0.1)),
        labels = {
          atk: 'Útok',
          def: 'Obrana',
          hp: 'HP',
          mp: 'MP',
          str: 'SÍL',
          vit: 'VIT',
          dex: 'POH',
          int: 'INT',
          crit: 'Krit %',
          spd: 'Pohyb',
          aspd: 'Rychlost útoku %',
          poison: 'Jed %',
          pierce: 'Průnik %',
          evade: 'Úhyb %',
        };
      detail.innerHTML =
        '<b style="color:' +
        r.col +
        '">' +
        esc(itemTitle(it)) +
        '</b> · Lv. ' +
        it.level +
        ' · ' +
        r.name +
        '<br>' +
        Object.keys(labels)
          .filter((k) => it[k])
          .map((k) => labels[k] + ' +' + it[k])
          .join(' · ');
      for (let [txt, fn] of [
        ['Nasadit', equipSelected],
        ['Vylepšit (' + price + ' Yang)', () => upgrade(it)],
        ['Prodat · ' + fmtY(salePrice(it)) + ' Yang', sellItem],
      ]) {
        let b = document.createElement('button');
        b.className = 'action alt';
        b.textContent = txt;
        b.onclick = fn;
        acts.appendChild(b);
      }
    } else detail.textContent = 'Vyber předmět. Bonusy rychlosti útoku, kritu, jedu, průniku a úhybu se sčítají z výbavy.';
    let regions = $('regions');
    regions.innerHTML = '';
    REGIONS.forEach((name, i) => {
      let b = document.createElement('button');
      b.className = 'action ' + (regionView === i ? '' : 'alt');
      b.textContent = i + 1 + '. ' + name;
      b.onclick = () => {
        regionView = i;
        refreshUI();
      };
      regions.appendChild(b);
    });
    $('regionLabel').textContent = REGIONS[regionView];
    let travel = $('travel');
    travel.innerHTML = '';
    for (let i = regionView * 6; i < regionView * 6 + 6; i++) {
      let b = document.createElement('button'),
        locked = i > maxUnlocked || player.level < ENTRY_LEVELS[i];
      b.className = (i === current ? 'active ' : '') + (locked ? 'locked' : '');
      b.textContent = mapCode(i) + (ENTRY_LEVELS[i] > 1 ? ' · Lv.' + ENTRY_LEVELS[i] : '');
      b.title = ROOM[i].title + ' · Lv. ' + ENTRY_LEVELS[i];
      b.disabled = locked;
      b.onclick = () => {
        if (paused) return;
        enterRoom(i);
        saveGame();
      };
      travel.appendChild(b);
    }
    let left = world.mobs.filter((m) => !m.dead).length;
    $('quest').innerHTML =
      '<strong>' +
      mapCode(current) +
      ' · ' +
      esc(ROOM[current].title) +
      '</strong><br>' +
      (isTown(current)
        ? 'Bezpečí, kovář, obchodník a léčitel.'
        : 'Nepřátelé: ' +
          left +
          ' · Metiny: ' +
          world.stones.filter((m) => !m.dead).length +
          '<br>' +
          (world.clear ? 'Portál otevřen.' : 'Vyčisti oblast a otevři další portál.') +
          '<div class="qbar"><i style="width:' +
          (world.total ? Math.round((100 * world.kills) / world.total) : 100) +
          '%"></i></div>') +
      (current % 6 === 5
        ? '<span class="area-req">Boss: doporučeno Lv. ' +
          [18, 35, 50][regionOf(current)] +
          ', vylepšená výbava a zásoba lektvarů. Ústup do jiné oblasti obnoví životy živého bosse.</span>'
        : '') +
      (current < ROOM.length - 1
        ? '<span class="area-req">Další oblast: ' + mapCode(current + 1) + ' · Lv. ' + ENTRY_LEVELS[current + 1] + '</span>'
        : '');
    refreshContract();
    renderSkills();
  }
  function renderBaseStats() {
    if (!player) return;
    let s = stats();
    $('hudName').textContent = player.name + ' · ' + CLASSES[player.cls].name;
    $('hudLvl').textContent = 'Lv. ' + player.level;
    $('hudHp').textContent = fmt(player.hp) + ' / ' + fmt(s.maxHp);
    $('hudMp').textContent = fmt(player.mp) + ' / ' + fmt(s.maxMp);
    $('hudXp').textContent = fmt(player.xp) + ' / ' + fmt(needXp(player.level));
    $('hpBar').style.width = (player.hp / s.maxHp) * 100 + '%';
    $('mpBar').style.width = (player.mp / s.maxMp) * 100 + '%';
    $('xpBar').style.width = (player.xp / needXp(player.level)) * 100 + '%';
    $('mapName').textContent = mapCode(current) + ' · ' + ROOM[current].title;
    $('mapSubtitle').textContent = ROOM[current].desc;
    $('className').textContent = schoolInfo().name;
    $('statAtk').textContent = s.atk + ' / ' + s.def;
    $('statGold').textContent = fmtY(player.gold);
    $('statStr').textContent = player.str + ' / ' + player.vit;
    $('statDex').textContent = player.dex + ' / ' + player.int;
    $('powerNum').textContent = 'Síla ' + (s.atk + s.def);
    $('pointsBox').textContent =
      (player.points ? 'Body: ' + player.points + ' · ' : '') +
      'Útok +' +
      Math.round(s.aspd) +
      ' % · Krit ' +
      Math.round(s.crit) +
      ' % · Jed ' +
      Math.round(s.poison) +
      ' % · Průnik ' +
      Math.round(s.pierce) +
      ' % · Úhyb ' +
      Math.round(s.evade) +
      ' %';
    let box = $('pointButtons'),
      want = player.points ? 'on' : 'off';
    // v119: tlačítka se nepřestavují při každém vykreslení – jinak se rychlé kliknutí ztratí
    if (box.dataset.v119 !== want || box.children.length !== (player.points ? 4 : 0)) {
      box.dataset.v119 = want;
      box.innerHTML = '';
    } else want = '';
    if (player.points && want)
      for (let [k, name] of [
        ['str', 'SÍL'],
        ['vit', 'VIT'],
        ['dex', 'OBR'],
        ['int', 'INT'],
      ]) {
        let b = document.createElement('button');
        b.className = 'action alt';
        b.textContent = '+ ' + name;
        b.onclick = () => addPoint(k);
        box.appendChild(b);
      }
    for (let e of $('skills').querySelectorAll('.ability[data-skill]')) {
      let i = Number(e.dataset.skill),
        v = player.cd[i] - time,
        co = e.querySelector('.cool');
      co.textContent = v > 0 ? v.toFixed(1) + 's' : '';
      co.classList.toggle('hidden', v <= 0);
      e.querySelector('.lv').textContent = skillGrade(i);
    }
    for (let e of $('skills').querySelectorAll('[data-potion]')) e.querySelector('small').textContent = '×' + player[e.dataset.potion];
    $('respawnInfo').textContent = isTown(current)
      ? 'Město bez nepřátel'
      : world.respawnAt != null
        ? 'Respawn za ' + Math.max(0, Math.ceil(world.respawnAt - time)) + ' s'
        : 'Respawn po porážce všech nepřátel a metinů';
    if (time - lastMetaRefresh > 1) {
      lastMetaRefresh = time;
      refreshContract();
    }
  }

  

