  // Procedural art is embedded code: no network or asset downloads are needed.
  function gradient(g, x, y, w, h, a, b) {
    let q = g.createLinearGradient(x, y, x + w, y + h);
    q.addColorStop(0, a);
    q.addColorStop(1, b);
    return q;
  }
  function artOval(g, x, y, rx, ry, fill, stroke) {
    g.beginPath();
    g.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
    g.fillStyle = fill;
    g.fill();
    if (stroke) {
      g.strokeStyle = stroke;
      g.lineWidth = 1;
      g.stroke();
    }
  }
  function artPoly(g, p, fill, stroke) {
    g.beginPath();
    g.moveTo(p[0][0], p[0][1]);
    for (let q of p.slice(1)) g.lineTo(q[0], q[1]);
    g.closePath();
    g.fillStyle = fill;
    g.fill();
    if (stroke) {
      g.strokeStyle = stroke;
      g.lineWidth = 1;
      g.stroke();
    }
  }
  
  
  
  
  
  
  
  
  
  
  

  
  
  
  
  
  
  

