      hpLeft: hp,
      hpWidth: clamp((Math.min(player.potionHP || 0, s.maxHp - player.hp) / s.maxHp) * 100, 0, 100),
      mpLeft: mp,
      mpWidth: clamp((Math.min(player.potionMP || 0, s.maxMp - player.mp) / s.maxMp) * 100, 0, 100),
      hpReserve: player.potionHP || 0,
