    player.specialItems[key]--;
    if (key === 'upgradeScroll') player.guaranteedUpgrade = true;
    else player.specialUntil[key] = Math.max(time, player.specialUntil[key]) + SPECIAL_ITEMS[key].duration;
    activityAt = time;
    circleFx(player.x, player.y, SPECIAL_ITEMS[key].col, 60);
    notify(key === 'upgradeScroll' ? 'Příští vylepšení: 100 %' : SPECIAL_ITEMS[key].name + ' aktivní · 30 minut');
    refreshUI();
