    economyState();
    let index = selectedItem,
      price = salePrice(it),
      before = player.buyback,
      oldSaved = roster.characters[player.id],
      oldActive = roster.activeId;
    inventory.splice(index, 1);
    player.gold += price;
    player.buyback = [{ buybackId: charId(), item: JSONcopy(it), price }, ...before].slice(0, 5);
    selectedItem = -1;
