    blobs.sort((a, b) => a[1] - b[1]);
    for (let [x, y, s] of blobs) v38Oval(g, x, y, s, s * 0.8, v38Lin(g, x - s, y - s, x + s, y + s, [col[2], col[1], col[0]]));
    for (let k = 0; k < 30; k++) v38Oval(g, (r() - 0.5) * 50, -14 - r() * 18, 1.6, 1, v38Rgba(col[2], 0.7));
