    vitL: { name: 'Velký kámen vitality', short: 'VIT', col: '#ff4aa8', stat: 'vit', value: 10, big: true, from: 'vit' },
    intL: { name: 'Velký kámen inteligence', short: 'INT', col: '#3a8aff', stat: 'int', value: 10, big: true, from: 'int' },
