      idx = s.indexOf(null),
      gems = v39Gems();
    if (idx < 0 || !gems[key]) return false;
    let old = s.slice(),
      oldSaved = roster.characters[player.id],
      oldActive = roster.activeId;
    it.sockets[idx] = key;
