    if (
      !commitTrade(
        () => {
          it.sockets = old;
          gems[key]++;
        },
        oldSaved,
        oldActive,
      )
    )
      return false;
    notify(V39_GEMS[key].name + ' vsazen · +' + V39_GEMS[key].value + ' ' + V39_GEMS[key].short);
