  // ---------------- Jedovatý oblak: pomalý putující oblak ----------------
  function isPoisonCloudSkill(i, q) {
    return player?.cls === 'ninja' && player.school === 'dagger' && i === 2 && q?.type === 'poisonCloud';
  }
  function launchPoisonCloud(i, q, angle) {
    let dx = Math.cos(angle),
      dy = Math.sin(angle),
      P = v39PowerOf(q),
      radius = Math.round([64, 80, 98, 122][spellRankTier(q)] * (1 + (P % 1) * 0.06)),
      speed = 105,
      life = 3.6 + P * 0.25,
      z = {
        ...rankTag(q),
        variant: 'v39cloud',
        room: current,
        x: clamp(player.x + dx * 50, 45, W - 45),
        y: clamp(player.y + dy * 50, 62, H - 50),
        vx: dx * speed,
        vy: dy * speed,
        radius,
        start: time,
        end: time + life,
        // obecná logika zón: next=∞ → nikdy netiká, remaining>0 → nevyřadí se
        next: Infinity,
        remaining: 1,
        tickAt: time + 0.5,
        interval: 0.5,
        damage: q.damage * 0.18,
        touch: q.damage * 0.5,
        touched: [],
        skillName: q.name,
        poisonQ: { stats: { skillAtk: q.stats?.skillAtk || 0 }, grade: q.grade || 1 },
        col: '#66aa83',
      };
    combatZones.push(z);
    spark(z.x, z.y - 16, spellColor(q), 10 + Math.round(P * 4), 120);
    player.buffs.stealth = 0;
    log(q.name + ' · ' + q.cooldown.toFixed(1) + ' s obnovy');
    refreshUI();
  }
  function v39TickClouds(dt) {
    for (let z of combatZones) {
      if (z.variant !== 'v39cloud' || z.room !== current) continue;
      if (time >= z.end) {
        z.remaining = 0;
        continue;
      }
      if (z.vx || z.vy) {
        let nx = z.x + z.vx * dt,
          ny = z.y + z.vy * dt;
        if (nx < 40 || nx > W - 40 || ny < 60 || ny > H - 40) z.vx = z.vy = 0;
        else {
          z.x = nx;
          z.y = ny;
        }
        if (z.end - time < 1) {
          let k = Math.pow(0.2, dt);
          z.vx *= k;
          z.vy *= k;
        }
      }
      if (!Array.isArray(z.touched)) z.touched = [];
      for (let m of allTargets()) {
        if (m.dead || z.touched.includes(m.id) || d2(m, z) >= z.radius + (m.r || 20)) continue;
        z.touched.push(m.id);
        hit(m, z.touch, z.skillName || 'poisonCloud');
        if (!m.dead && z.poisonQ) inflictPoison(m, z.poisonQ);
      }
      if (time >= z.tickAt) {
        z.tickAt = time + (z.interval || 0.5);
        v111Zone(z, () => {
          for (let m of allTargets()) if (!m.dead && d2(m, z) < z.radius + (m.r || 20)) hit(m, z.damage, 'poison');
        });
      }
    }
  }
  function tickCombat(dt) {
    tickCombatV38(dt);
    if (player && !isDead()) v39TickClouds(dt);
  }
  function applySkillV40b(i, q, angle) {
    if (player && !isDead() && isPoisonCloudSkill(i, q)) return launchPoisonCloud(i, q, angle);
    return applySkillV38(i, q, angle);
  }
  function spellImpact(a) {
    if (isPoisonCloudSkill(a.i, a.q)) return;
    return spellImpactV38(a);
  }


// ---- v39_fire.js ----
