  // Živý plamen: lávové jádro, plápolající jazyky a žhnoucí oči.
  function v39PaintFlameMob(g, m, st, B, r, atk) {
    let s = r / 30,
      t = time * 3 + (m.id || 0) * 1.7,
      bob = Math.sin(t) * 2 - 4;
    g.save();
    g.scale(s, s);
    v38Glow(0, -24, 40, '#ff6a1a', 0.32 + Math.sin(t * 1.3) * 0.06);
    g.translate(0, bob);
    // jazyky plamene (za tělem)
    g.save();
    g.globalCompositeOperation = 'screen';
    for (let k = 0; k < 5; k++) {
      let x = (k - 2) * 6,
        h = 30 + Math.sin(t * 2 + k * 1.7) * 7 + (k === 2 ? 10 : 0),
        sw = Math.sin(t * 2.4 + k) * 4;
      g.beginPath();
      g.moveTo(x - 7, -16);
      g.quadraticCurveTo(x - 6 + sw, -16 - h * 0.6, x + sw * 1.4, -16 - h);
      g.quadraticCurveTo(x + 6 + sw, -16 - h * 0.55, x + 7, -16);
      g.closePath();
      g.fillStyle = v38Lin(g, 0, -16 - h, 0, -10, ['rgba(255,240,150,0)', 'rgba(255,170,60,.85)', 'rgba(255,90,20,.9)']);
      g.fill();
    }
    g.restore();
    // lávové jádro
    let core = g.createRadialGradient(-3, -26, 2, 0, -22, 19);
    core.addColorStop(0, '#fff6c0');
    core.addColorStop(0.35, '#ffb040');
    core.addColorStop(0.75, '#e0461a');
    core.addColorStop(1, '#6a1408');
    g.fillStyle = core;
    g.beginPath();
    g.ellipse(0, -22, 15, 18, 0, 0, Math.PI * 2);
    g.fill();
    g.strokeStyle = 'rgba(60,10,4,.8)';
    g.lineWidth = 1.2;
    g.stroke();
    // ruce z plamene
    let lift = atk * 1.1;
    for (let i of [-1, 1]) {
      g.save();
      g.translate(i * 13, -26);
      g.rotate(i * (0.5 + Math.sin(t * 2 + i) * 0.2) - (i > 0 ? lift : 0));
      g.beginPath();
      g.moveTo(0, -3);
      g.quadraticCurveTo(i * 10, 2, i * 14, 10 + Math.sin(t * 3) * 2);
      g.quadraticCurveTo(i * 6, 6, 0, 4);
      g.closePath();
      g.fillStyle = '#ff8a2a';
      g.fill();
      g.restore();
    }
    // oči
    for (let i of [-1, 1]) {
      v38Oval(g, i * 5, -27, 3.2, 2.4, '#fffbe0');
      v38Oval(g, i * 5 + 0.6, -27, 1.4, 1.6, '#3a0a04');
    }
    v38Oval(g, 0, -18, 4, 1.6 + atk * 2, '#5a0e04');
    g.restore();
    // jiskry
    for (let k = 0; k < 3; k++) {
      let q = (time * 0.9 + k / 3 + (m.id || 0) * 0.13) % 1;
      v38Glow(Math.sin(k * 2.1 + time) * 10 * s, (-40 - q * 30) * s, 3 * s, '#ffd27a', 0.8 * (1 - q));
    }
  }
  // Duch plamenů metá ohnivé koule místo šípů.
  function shoot(x, y, angle, damage, speed, range, col, owner = 'player', poison = 0, scale = 1) {
    let out = shootV38(x, y, angle, damage, speed, range, col, owner, poison, scale);
    if (owner === 'enemy' && world?.mobs) {
      let m = world.mobs.find((m) => m.x === x && m.y === y && m.type === 'flameSpirit');
      let p = projectiles.at(-1);
      if (m && p) {
        p.style = 'magic';
        p.col = '#ff8a3a';
        p.fireball = true;
      }
    }
    return out;
  }
  // ---------------- terén Ohnivé země ----------------
  const V39_LAVA = { room: -1, pools: [] };
  function v39LavaCrack(g, pts, w) {
    let path = () => {
      g.beginPath();
      g.moveTo(pts[0][0], pts[0][1]);
      for (let p of pts) g.lineTo(p[0], p[1]);
    };
    g.lineCap = g.lineJoin = 'round';
    path();
    g.strokeStyle = 'rgba(20,6,2,.75)';
    g.lineWidth = w + 5;
    g.stroke();
    path();
    g.strokeStyle = 'rgba(255,80,20,.35)';
    g.lineWidth = w + 3;
    g.stroke();
    path();
    g.strokeStyle = '#ff6a1a';
    g.lineWidth = w;
    g.stroke();
    path();
    g.strokeStyle = '#ffd27a';
    g.lineWidth = Math.max(0.8, w * 0.35);
    g.stroke();
  }
  function v39PaintLavaFields(g, rand, town, idx) {
    V39_LAVA.room = idx;
    V39_LAVA.pools = [];
    g.save();
    // popel a tmavé čedičové plotny
    for (let k = 0; k < 60; k++) {
      let x = rand() * W,
        y = rand() * H,
        s = 14 + rand() * 40;
      v38Oval(g, x, y, s, s * 0.55, v38Rgba(rand() > 0.5 ? '#1e120e' : '#5a4034', 0.18), null, 1, rand() * 3);
    }
    // praskliny s lávou
    let cracks = town ? 6 : 14;
    for (let k = 0; k < cracks; k++) {
      let x = rand() * W,
        y = rand() * H,
        a = rand() * Math.PI * 2,
        pts = [[x, y]];
      if (town && x > 160 && x < 940 && y > 210 && y < 470) continue;
      for (let s = 0; s < 6 + Math.floor(rand() * 6); s++) {
        a += (rand() - 0.5) * 1.2;
        x += Math.cos(a) * (14 + rand() * 20);
        y += Math.sin(a) * (10 + rand() * 14);
        pts.push([x, y]);
      }
      v39LavaCrack(g, pts, 1.6 + rand() * 2.2);
      // drobné odbočky
      let b = pts[Math.floor(pts.length / 2)];
      v39LavaCrack(g, [b, [b[0] + (rand() - 0.5) * 40, b[1] + (rand() - 0.5) * 30]], 1.2);
    }
    // lávová jezírka u okrajů (mimo cestu a náměstí)
    let pools = town ? 2 : 3;
    for (let k = 0; k < pools; k++) {
      let x = 140 + rand() * 820,
        y = rand() > 0.5 ? 120 + rand() * 50 : 520 + rand() * 50,
        rx = 46 + rand() * 40,
        ry = rx * (0.42 + rand() * 0.12);
      if (Math.abs(y - v38RoadY(x)) < 110) continue;
      V39_LAVA.pools.push({ x, y, rx, ry });
      v38Oval(g, x + 3, y + 4, rx + 10, ry + 7, 'rgba(15,5,2,.55)');
      let lava = g.createRadialGradient(-rx * 0.2, -rx * 0.2, 2, 0, 0, rx);
      lava.addColorStop(0, '#fff2a8');
      lava.addColorStop(0.3, '#ffb03a');
      lava.addColorStop(0.7, '#e8461a');
      lava.addColorStop(1, '#7a1808');
      g.save();
      g.translate(x, y);
      g.scale(1, ry / rx);
      g.fillStyle = lava;
      g.beginPath();
      g.arc(0, 0, rx, 0, Math.PI * 2);
      g.fill();
      g.restore();
      // chladnoucí kůra
      for (let c = 0; c < 7; c++) {
        let a = rand() * Math.PI * 2,
          d = rand() * 0.7,
          px = x + Math.cos(a) * rx * d,
          py = y + Math.sin(a) * ry * d;
        v38Fill(g, [[px - 8, py], [px - 2, py - 4], [px + 7, py - 2], [px + 5, py + 3], [px - 4, py + 3]], 'rgba(60,20,10,.75)', 'rgba(255,140,60,.5)', 0.8);
      }
      v38Oval(g, x, y, rx, ry, null, 'rgba(30,10,4,.9)', 3);
      v38Oval(g, x, y, rx + 4, ry + 3, null, 'rgba(255,120,40,.35)', 2);
    }
    g.restore();
  }
  function v39DrawLavaGlow() {
    if (V39_LAVA.room !== current) return;
    cx.save();
    for (let [k, p] of V39_LAVA.pools.entries()) {
      v38Glow(p.x, p.y, p.rx * 1.5, '#ff7a2a', 0.22 + Math.sin(time * 1.6 + k * 2) * 0.07, 0.55);
      // bublání
      let q = (time * 0.7 + k * 0.37) % 1,
        a = k * 2.1 + Math.floor(time * 0.7 + k * 0.37) * 1.7;
      v38Oval(cx, p.x + Math.cos(a) * p.rx * 0.4, p.y + Math.sin(a) * p.ry * 0.4, 2 + q * 5, 1 + q * 2.5, null, v38Rgba('#fff0a0', 0.7 * (1 - q)), 1);
    }
    cx.restore();
  }
  function v39PaintLavaRock(g, r, s) {
    v38PaintRock(g, r, '#3c2c27', s);
    g.save();
    g.scale(s, s);
    g.globalCompositeOperation = 'screen';
    g.lineCap = 'round';
    for (let k = 0; k < 3; k++) {
      let x = -20 + r() * 40,
        y = -28 + r() * 26;
      g.strokeStyle = 'rgba(255,110,30,.85)';
      g.lineWidth = 1.6;
      g.beginPath();
      g.moveTo(x, y);
      g.lineTo(x + (r() - 0.5) * 16, y + 6 + r() * 8);
      g.lineTo(x + (r() - 0.5) * 18, y + 14 + r() * 8);
      g.stroke();
    }
    g.restore();
  }


