      if (pointSegment(player, c.origin, c.end) < c.width + PLAYER_HIT_RADIUS) bossHurt(bossDamage(m, V40_PIERCE_FACTOR), c.origin.x, c.origin.y, 0.5, 60);
      m.x = c.end.x;
      m.y = c.end.y;
