  Object.assign(V38_BEAST, {
    goldGuardian: { fam: 'golem', stone: '#c8a040', glow: '#fff0a0' },
    goldSnake: { fam: 'snake', body: '#e8b838', belly: '#fff2b8', pattern: '#8a5a10', hood: true, eyes: '#ff3a2a' },
  });
  // terén zlaté jeskyně: tmavá skála, zlaté žíly, nugety, krápníky
  const V40_VEINS = { room: -1, glints: [] };
  function v40PaintGoldCave(g, rand, town, idx) {
    V40_VEINS.room = idx;
    V40_VEINS.glints = [];
    g.save();
    // tmavé skalní plotny
    for (let k = 0; k < 70; k++) {
      let x = rand() * W,
        y = rand() * H,
        s = 16 + rand() * 46;
      v38Oval(g, x, y, s, s * 0.5, v38Rgba(rand() > 0.5 ? '#14110d' : '#4a4234', 0.2), null, 1, rand() * 3);
    }
    // zlaté žíly
    let veins = town ? 7 : 16;
    for (let k = 0; k < veins; k++) {
      let x = rand() * W,
        y = rand() * H,
        a = rand() * Math.PI * 2,
        pts = [[x, y]];
      if (town && x > 160 && x < 940 && y > 210 && y < 470) continue;
      for (let s = 0; s < 5 + Math.floor(rand() * 6); s++) {
        a += (rand() - 0.5) * 1.1;
        x += Math.cos(a) * (12 + rand() * 18);
        y += Math.sin(a) * (8 + rand() * 12);
        pts.push([x, y]);
      }
      let path = () => {
        g.beginPath();
        g.moveTo(pts[0][0], pts[0][1]);
        for (let p of pts) g.lineTo(p[0], p[1]);
      };
      g.lineCap = g.lineJoin = 'round';
      path();
      g.strokeStyle = 'rgba(10,8,4,.7)';
      g.lineWidth = 6;
      g.stroke();
      path();
      g.strokeStyle = '#a87a1c';
      g.lineWidth = 3.4;
      g.stroke();
      path();
      g.strokeStyle = '#ffe07a';
      g.lineWidth = 1.2;
      g.stroke();
      V40_VEINS.glints.push(pts[Math.floor(pts.length / 2)]);
    }
    // zlaté nugety a krystaly
    for (let k = 0; k < (town ? 14 : 30); k++) {
      let x = rand() * W,
        y = rand() * H,
        s = 2 + rand() * 4;
      if (Math.abs(y - v38RoadY(x)) < 50) continue;
      v38Fill(g, [[x - s, y], [x - s * 0.3, y - s], [x + s, y - s * 0.4], [x + s * 0.6, y + s * 0.6]], v38Lin(g, x - s, y - s, x + s, y + s, ['#fff2a8', '#d8a020', '#6a4a08']), 'rgba(30,20,4,.8)', 0.6);
    }
    // stalagmity u okrajů
    for (let k = 0; k < 18; k++) {
      let x = rand() * W,
        y = rand() > 0.5 ? 70 + rand() * 60 : H - 60 - rand() * 50,
        h = 14 + rand() * 22,
        w = 5 + rand() * 6;
      v38Oval(g, x, y + 2, w * 1.4, w * 0.5, 'rgba(0,0,0,.4)');
      v38Fill(g, [[x - w, y], [x - w * 0.3, y - h * 0.7], [x, y - h], [x + w * 0.4, y - h * 0.6], [x + w, y]], v38Lin(g, x - w, y - h, x + w, y, ['#6a604e', '#3a342a', '#1a1612']), 'rgba(10,8,6,.8)', 0.8);
    }
    g.restore();
  }
  function v40DrawGoldGlow() {
    if (V40_VEINS.room !== current) return;
    for (let [k, p] of V40_VEINS.glints.entries()) {
      let a = 0.18 + Math.sin(time * 1.3 + k * 1.7) * 0.08;
      v38Glow(p[0], p[1], 34, '#ffd75a', a, 0.55);
      let q = (time * 0.5 + k * 0.29) % 1;
      if (q < 0.25) v38Glow(p[0] + Math.sin(k) * 10, p[1] - 4, 6, '#fffbe0', (0.25 - q) * 3);
    }
    if (current === V40_FIRE_GATE_ROOM) v40DrawGateHint();
  }
  function v40DrawGateHint() {}
  // Portál do jeskyně v Ohnivé zemi (nahoře) – zlatá brána
  function v38Portals() {
    let list = v38PortalsV40b();
    if (current === V40_FIRE_GATE_ROOM) list.push({ x: V40_GATE.x, y: V40_GATE.y, label: 'Zlatá jeskyně', kind: 'gold', open: v40GoldUnlocked() });
    for (let p of list) {
      if (p.kind === 'next' && (current === V40_FIRST - 1 || current === V40_LAST)) p.label = 'Tábor';
      if (p.kind === 'prev' && current === V40_FIRST) p.label = 'Ohnivá země';
    }
    return list;
  }
  // Zlatá křídla: velká zlatá péřová křídla s jemným máváním a jiskrami
  function v40GoldWings(g, w, p, shY) {
    let t = time,
      flap = Math.sin(t * 1.8) * 0.1 + (p.moving || 0) * 0.05,
      ws = 0.88;
    // záře za křídly
    g.save();
    let halo = g.createRadialGradient(0, shY - 6, 4, 0, shY - 6, 56);
    halo.addColorStop(0, 'rgba(255,230,140,.35)');
    halo.addColorStop(1, 'rgba(255,200,80,0)');
    g.fillStyle = halo;
    g.beginPath();
    g.arc(0, shY - 6, 56, 0, Math.PI * 2);
    g.fill();
    g.restore();
    for (let side of [-1, 1]) {
      g.save();
      g.translate(side * 3, shY + 3);
      g.scale(side * ws, ws);
      g.rotate(-flap - 0.12);
      // tři řady per
      for (let row = 0; row < 3; row++) {
        let n = 8 - row,
          len0 = [58, 44, 30][row],
          cols = [
            ['#fff6c8', '#f2c443', '#a8741a'],
            ['#fff0b0', '#e8b030', '#8a5a10'],
            ['#ffffff', '#ffe08a', '#c89028'],
          ][row];
        for (let j = 0; j < n; j++) {
          let q = j / (n - 1),
            len = len0 - j * (row ? 3 : 4) + Math.sin(t * 2 + j) * 0.8,
            a = -1.15 + q * 1.35 + row * 0.08;
          g.save();
          g.rotate(a);
          g.beginPath();
          g.moveTo(0, 0);
          g.quadraticCurveTo(len * 0.5, -7, len, -1.5);
          g.quadraticCurveTo(len * 0.55, 5, 0, 3.5);
          g.closePath();
          g.fillStyle = v38Lin(g, 0, -6, len, 4, cols);
          g.fill();
          g.strokeStyle = 'rgba(90,56,8,.55)';
          g.lineWidth = 0.6;
          g.stroke();
          v38Line(g, 2, 1, len * 0.85, -1, 'rgba(255,255,230,.55)', 0.5);
          g.restore();
        }
      }
      // jiskry podél křídla
      for (let k = 0; k < 4; k++) {
        let q = (t * 0.6 + k / 4 + side * 0.13) % 1,
          x = 12 + k * 11,
          y = -18 - k * 5 + q * 26;
        g.fillStyle = 'rgba(255,250,210,' + (0.9 * (1 - q)).toFixed(3) + ')';
        g.beginPath();
        g.moveTo(x, y - 2.4);
        g.lineTo(x + 1, y);
        g.lineTo(x, y + 2.4);
        g.lineTo(x - 1, y);
        g.closePath();
        g.fill();
      }
      g.restore();
    }
  }
  function v40PaintGoldWingsIcon(g) {
    let halo = g.createRadialGradient(0, -2, 2, 0, -2, 34);
    halo.addColorStop(0, 'rgba(255,230,140,.55)');
    halo.addColorStop(1, 'rgba(255,200,80,0)');
    g.fillStyle = halo;
    g.fillRect(-36, -36, 72, 72);
    for (let side of [-1, 1]) {
      g.save();
      g.scale(side, 1);
      g.translate(2, 6);
      for (let j = 0; j < 7; j++) {
        g.save();
        g.rotate(-1.1 + j * 0.2);
        v38Fill(g, [[0, 0], [16, -6], [34 - j * 2, -1], [16, 4]], v38Lin(g, 0, -6, 32, 4, ['#fff6c8', '#f2c443', '#8a5a10']), 'rgba(90,56,8,.8)', 0.7);
        g.restore();
      }
      g.restore();
    }
    v38Star(g, 0, -12, 4, '#fffbe0');
  }
  function v40IconBackdrop(g, S, col) {
    let q = g.createRadialGradient(S / 2, S / 2, 2, S / 2, S / 2, S * 0.62);
    q.addColorStop(0, v38Rgba(col, 0.6));
    q.addColorStop(0.55, v38Rgba(col, 0.22));
    q.addColorStop(1, v38Rgba(col, 0));
    g.fillStyle = q;
    g.fillRect(0, 0, S, S);
    // paprsky
    g.save();
    g.translate(S / 2, S / 2);
    g.globalAlpha = 0.25;
    for (let k = 0; k < 8; k++) {
      g.rotate(Math.PI / 4);
      g.fillStyle = v38Rgba(col, 0.6);
      g.beginPath();
      g.moveTo(-2, 0);
      g.lineTo(0, -S * 0.5);
      g.lineTo(2, 0);
      g.fill();
    }
    g.restore();
  }

