  function v40BossRows() {
    let def = player ? stats().def : 0,
      rows = [],
      list = [
        ['boss', 'Vlčí výpad', 1.35, false],
        ['general', 'Vějíř šípů (1 šíp)', 0.78, false],
        ['general', 'Ohnivé dopady', 1.1, false],
        ['orcChief', 'Úder kladivem', 1.65, false],
        ['orcChief', 'Tlakový kruh', 1.2, false],
        ['desertTurtle', 'Výbuch', 1.45, false],
        ['nineTails', 'Ledová střela', 1.15, false],
        ['nineTails', 'Smršť ocasů', 1.3, false],
        ['demonKing', 'Pekelná střela', 1.05, false],
        ['demonKing', 'Vysávání duše', 1.45, false],
        ['flameKing', 'Ohnivý déšť (dopad)', 1.05, true],
        ['flameKing', 'Plamenná vlna', 1.25, true],
        ['flameKing', 'Plamenný průraz', V40_PIERCE_FACTOR, true],
        ['goldSnake', 'Jedový plivanec', 1.0, true],
        ['goldSnake', 'Ocasní smršť', 1.3, true],
        ['goldSnake', 'Hadí výpad', 1.6, true],
      ];
    for (let [type, name, f, magic] of list) {
      if (!TYPES[type]) continue;
      let m = { type, phase: 1, weakenUntil: 0 },
        raw = bossDamage(m, f) * V40_MOB_DAMAGE,
        rage = bossDamage({ ...m, phase: 2 }, f) * V40_MOB_DAMAGE,
        pen = magic ? 1 : TYPES[type].goldCave ? V40_ARMOR_PEN : 0,
        after = (raw * 100) / (100 + def * (1 - pen) * 2.1);
      rows.push([esc(TYPES[type].name), esc(name) + (magic ? ' · magie' : ''), fmt(Math.round(raw)), fmt(Math.round(rage)), fmt(Math.round(after))]);
    }
    for (let type of ['demonKing', 'flameKing', 'goldSnake'])
      if (TYPES[type]) {
        let raw = TYPES[type].dmg * BALANCE.bossDamage * V40_MOB_DAMAGE,
          pen = TYPES[type].goldCave ? V40_ARMOR_PEN : 0;
        rows.push([esc(TYPES[type].name), 'Útok zblízka', fmt(Math.round(raw)), fmt(Math.round(raw * 1.18)), fmt(Math.round((raw * 100) / (100 + def * (1 - pen) * 2.1)))]);
      }
    return rows;
  }
