  // ===================================================================
  // v41: level kořisti, strana příchodu, škálování tříd, filtr bílých
  //      předmětů, sdílená truhla jen na šerpy a užitkové předměty
  // ===================================================================
  // Level předmětu: většinou level hráče, občas +1, zřídka −1, vzácně +2 (nikdy nad level zdroje).
  const V41_LOOT_OFFSETS = [
    [-1, 0.08],
    [0, 0.72],
    [1, 0.17],
    [2, 0.03],
  ];
  function lootLevel(sourceLevel) {
    let src = Math.max(1, Math.floor(Number(sourceLevel) || 1)),
      r = Math.random(),
      off = 0;
    for (let [o, p] of V41_LOOT_OFFSETS) if ((r -= p) < 0) {
      off = o;
      break;
    }
    return Math.max(1, Math.min(src, (player?.level || 1) + off));
  }
  // Strana příchodu: dopředu = vlevo (u zpětné brány), zpět = vpravo (u brány dál).
  function v41PlaceArrival(dir, from) {
    if (!player || !world) return;
    let town = isTown(current);
    if (dir === 'prev' || (dir === 'next' && current < from)) {
      player.x = W - (town ? 220 : 140);
      player.y = 330;
    } else if (dir === 'next') {
      player.x = town ? 220 : 140;
      player.y = 330;
    }
  }
  // Třídy se škálováním INT (sura, šaman): kouzla +10 %; se SÍL (válečník, lykan): autoattack +10 %.
  function v41ClassMult(kind) {
    let main = CLASS_SCALING[player?.cls] || {},
      intMain = (main.int || 0) >= Math.max(main.str || 0, main.dex || 0),
      strMain = (main.str || 0) >= Math.max(main.int || 0, main.dex || 0);
    if (kind === 'basic') return strMain ? 1.1 : 1;
    return intMain ? 1.1 : 1;
  }
  // Filtr kořisti (nastavení)
  const V41_FILTER_KEY = 'joan-loot-filter-v41';
  function v41Filter() {
    if (V40.filter) return V40.filter;
    let f = { ignoreWhite: false, ignoreBlue: false, ignorePurple: false };
    try {
      Object.assign(f, JSON.parse(localStorage.getItem(V41_FILTER_KEY) || '{}'));
    } catch (e) {}
    return (V40.filter = f);
  }
  function v41SetFilter(key, value) {
    v41Filter()[key] = value;
    try {
      localStorage.setItem(V41_FILTER_KEY, JSON.stringify(V40.filter));
    } catch (e) {}
  }
  function showAudioSettingsV65b() {
    let out = showAudioSettingsV40b();
    let body = $('choiceBody');
    if (body && !body.querySelector('.v41-loot-settings')) {
      let box = document.createElement('section');
      box.className = 'v41-loot-settings';
      box.innerHTML =
        '<h3>Kořist</h3><label class="v41-check"><input type="checkbox" id="v41IgnoreWhite"' +
        (v41Filter().ignoreWhite ? ' checked' : '') +
        '> Ignorovat drop bílých (obyčejných) předmětů</label><label class="v41-check"><input type="checkbox" id="v41IgnoreBlue"' +
        (v41Filter().ignoreBlue ? ' checked' : '') +
        '> Ignorovat drop modrých (vzácných) předmětů</label><label class="v41-check"><input type="checkbox" id="v41IgnorePurple"' +
        (v41Filter().ignorePurple ? ' checked' : '') +
        '> Ignorovat drop fialových (epických) předmětů</label><small>Vybraná výbava se vůbec neobjeví na zemi. Legendární a mytické předměty, zlatý tier, šerpy, knihy a užitkové předměty padají vždy.</small>';
      body.appendChild(box);
      $('v41IgnoreWhite').onchange = (e) => {
        v41SetFilter('ignoreWhite', !!e.target.checked);
        notify(e.target.checked ? 'Bílé předměty se nebudou zobrazovat na zemi.' : 'Bílé předměty znovu padají.');
      };
      $('v41IgnoreBlue').onchange = (e) => {
        v41SetFilter('ignoreBlue', !!e.target.checked);
        notify(e.target.checked ? 'Modré předměty se nebudou zobrazovat na zemi.' : 'Modré předměty znovu padají.');
      };
      $('v41IgnorePurple').onchange = (e) => {
        v41SetFilter('ignorePurple', !!e.target.checked);
        notify(e.target.checked ? 'Fialové předměty se nebudou zobrazovat na zemi.' : 'Fialové předměty znovu padají.');
      };
    }
    return out;
  }
  // Šerpy vždy vyžadují level 1.
  function v41FixSash(it) {
    if (it && it.slot === 'sash' && it.level !== 1) it.level = 1;
    return it;
  }
  function makeLegendaryItemV71b(level, slot = null) {
    return v41FixSash(makeLegendaryItemV40b(level, slot));
  }
  function v41FixAllSashes() {
    for (let it of [...inventory, ...Object.values(equipped || {})]) v41FixSash(it);
    for (let e of roster?.sharedChest || []) if (e.kind === 'gear') v41FixSash(e.item);
    for (let e of player?.buyback || []) v41FixSash(e.item);
  }
  // Sdílená truhla: z výbavy jen šerpy.
  function v41ChestAllowed(it) {
    return !!it && it.slot === 'sash';
  }
  function depositChest(ref) {
    if (ref && typeof ref === 'object' && !v41ChestAllowed(ref)) {
      notify('Do sdílené truhly lze vložit jen šerpy, knihy, lektvary a užitkové předměty.');
      return false;
    }
    return depositChestV40b(ref);
  }
  

  // ===================================================================
  // v43: Kamufláž (škálování bonusu a trvání, funguje i na bosse),
  //      Víření kordů s vnějšími kruhy (M / G / P)
  // ===================================================================
  // První zásah z kamufláže: +15 % na Lv. 1 → +100 % na P
  function v41StealthBonus(q) {
    let P = typeof v39PowerOf === 'function' ? v39PowerOf(q) : spellRankTier(q);
    return 0.15 + 0.85 * clamp(P / 3, 0, 1);
  }
  
  function v41IsDaggerWhirl(i, q) {
    return player?.cls === 'ninja' && player.school === 'dagger' && i === 3 && q?.type === 'aoe';
  }
  const V41_RING_WIDTH = 0.16; // šířka každého vnějšího kruhu (podíl základního poloměru)
  const V41_RING_DAMAGE = 0.6;
  function applySkillV54b(i, q, angle) {
    let out = applySkillV40b(i, q, angle);
    if (player && !isDead() && v41IsDaggerWhirl(i, q) && q.v41Rings > 0) {
      let R = 105 * (q.areaScale || 1),
        w = R * V41_RING_WIDTH;
      for (let k = 1; k <= q.v41Rings; k++) {
        let inner = R + (k - 1) * w,
          outer = R + k * w;
        for (let m of allTargets()) {
          let d = d2(m, player);
          if (!m.dead && d >= inner + m.r && d < outer + m.r) hit(m, q.damage * V41_RING_DAMAGE, q.name);
        }
        effects.push({ type: 'spectralDaggers', x: player.x, y: player.y, radius: outer, count: (q.daggerCount || 3) + k * 2, stage: q.stage, col: k === 3 ? '#fff2b0' : '#b2f9de', life: 0.45 + k * 0.08, max: 0.45 + k * 0.08, ...rankTag(q) });
        circleFx(player.x, player.y, '#b2f9de', outer);
      }
    }
    return out;
  }


