  function v62Burst(t, age) {
    // záblesk a rozpínající se kruh za číslem
    let red = t.v62Red != null,
      dur = red ? 0.42 : 0.3;
    if (age > dur) return;
    let p = age / dur,
      col = red ? '255,60,80' : '255,230,150',
      R = (red ? 26 : 18) + p * (red ? 70 : 44);
    cx.save();
    cx.globalCompositeOperation = 'lighter';
    let g = cx.createRadialGradient(0, 0, 0, 0, 0, R);
    g.addColorStop(0, 'rgba(' + col + ',' + (0.55 * (1 - p)).toFixed(3) + ')');
    g.addColorStop(1, 'rgba(' + col + ',0)');
    cx.fillStyle = g;
    cx.beginPath();
    cx.arc(0, 0, R, 0, Math.PI * 2);
    cx.fill();
    cx.strokeStyle = 'rgba(' + col + ',' + (0.8 * (1 - p)).toFixed(3) + ')';
    cx.lineWidth = 3 * (1 - p) + 0.5;
    cx.beginPath();
    cx.ellipse(0, 0, R * 1.1, R * 0.62, 0, 0, Math.PI * 2);
    cx.stroke();
    if (red)
      for (let k = 0; k < 8; k++) {
        let a = (k / 8) * Math.PI * 2 + 0.3,
          r0 = R * 0.6,
          r1 = R * 1.25;
        cx.beginPath();
        cx.moveTo(Math.cos(a) * r0, Math.sin(a) * r0 * 0.6);
        cx.lineTo(Math.cos(a) * r1, Math.sin(a) * r1 * 0.6);
        cx.stroke();
      }
    cx.restore();
  }
