    let heal = Math.round(lost * B.healFromHit);
    m.hp = Math.min(m.maxHp, m.hp + heal);
    floatText(m.x + rnd(-10, 10), m.y - m.r - 24, '+' + fmt(heal), '#7ae07a', 15);
