  // ---------------- žraločí hlava ----------------
  function v38RigHead(g, s, p, shY, side, back) {
    if (s.face !== 'shark') return v38RigHeadV81b(g, s, p, shY, side, back);
    let skin = s.skin || '#5a7a8e',
      belly = '#e6eef2',
      hx = side ? 1.2 : 0,
      hy = shY - 9.5,
      ol = 'rgba(10,20,28,.6)';
    v38Box(g, -2.6, shY - 4, 5.2, 5, 2, v38Shade(skin, -0.2));
    // ploutev
    v38Fill(g, side ? [[hx - 4, hy - 6], [hx - 1, hy - 17], [hx + 3, hy - 6.5]] : [[hx - 2.6, hy - 7], [hx, hy - 17], [hx + 2.6, hy - 7]], v38Shade(skin, -0.12));
    if (side && !back) {
      g.beginPath();
      g.moveTo(hx - 6.5, hy + 6);
      g.quadraticCurveTo(hx - 8, hy - 7, hx - 1, hy - 8);
      g.quadraticCurveTo(hx + 9, hy - 7, hx + 14, hy + 0.5);
      g.quadraticCurveTo(hx + 11, hy + 6.5, hx + 2, hy + 7.5);
      g.closePath();
      g.fillStyle = v38Lin(g, hx, hy - 8, hx, hy + 8, [v38Shade(skin, 0.2), skin, v38Shade(skin, -0.25)]);
      g.fill();
      g.strokeStyle = ol;
      g.lineWidth = 0.8;
      g.stroke();
      // světlé břicho / spodní čelist
      g.beginPath();
      g.moveTo(hx - 5, hy + 5.5);
      g.quadraticCurveTo(hx + 4, hy + 3, hx + 12.5, hy + 2);
      g.quadraticCurveTo(hx + 10, hy + 6.5, hx + 2, hy + 7.4);
      g.closePath();
      g.fillStyle = belly;
      g.fill();
      // tlama se zuby
      v38Line(g, hx + 12, hy + 2.2, hx + 1, hy + 3.8, '#2a0a0e', 1);
      for (let i = 0; i < 5; i++) v38Fill(g, [[hx + 2 + i * 2, hy + 3.6 - i * 0.3], [hx + 3 + i * 2, hy + 5.2 - i * 0.3], [hx + 4 + i * 2, hy + 3.4 - i * 0.3]], '#ffffff');
      // oko a žábry
      v38Oval(g, hx + 5, hy - 1.8, 1.4, 1.4, '#0a0e12');
      v38Oval(g, hx + 5.4, hy - 2.2, 0.45, 0.45, '#ffffff');
      for (let i = 0; i < 3; i++) v38Line(g, hx - 2.5 + i * 1.6, hy - 1, hx - 3.2 + i * 1.6, hy + 3.5, v38Shade(skin, -0.35), 0.7);
      return;
    }
    v38Oval(g, hx, hy, 7.4, 8.4, v38Lin(g, hx - 7, hy - 8, hx + 7, hy + 8, [v38Shade(skin, 0.18), skin, v38Shade(skin, -0.28)]), ol, 0.8);
    if (back) return;
    v38Oval(g, hx, hy + 4, 6, 3.8, belly);
    // široká tlama se zuby
    g.beginPath();
    g.moveTo(hx - 5, hy + 2.5);
    g.quadraticCurveTo(hx, hy + 7, hx + 5, hy + 2.5);
    g.quadraticCurveTo(hx, hy + 4.4, hx - 5, hy + 2.5);
    g.fillStyle = '#3a0a10';
    g.fill();
    for (let i = -2; i <= 2; i++) v38Fill(g, [[hx + i * 1.9 - 0.8, hy + 3.1], [hx + i * 1.9, hy + 4.6], [hx + i * 1.9 + 0.8, hy + 3.1]], '#ffffff');
    // oči po stranách
    v38Oval(g, hx - 5, hy - 1.5, 1.3, 1.5, '#0a0e12');
    v38Oval(g, hx + 5, hy - 1.5, 1.3, 1.5, '#0a0e12');
  }
