// ---- v93_reset.js ----
  // ===================================================================
  // v93: reset instance bossů Akasuzuki – při odchodu z arény, příchodu do ní i načtení hry
  //      se celý boj obnoví: nový boss (plné HP, intro, všechny mechaniky od začátku),
  //      bez strážců, klonů, vody, projektilů a zbytkových stavů.
  //      Během probíhajícího boje se mechaniky na prazích HP spouští jen jednou (stav drží boss).
  // ===================================================================
  const V93_ARENAS = { [V63_ARENA]: V63_BOSS, [V77_ROOM]: V77_BOSS, [V81_ROOM]: V81_BOSS, [V85_ROOM]: V85_BOSS, [V89_ROOM]: V89_BOSS };
  const V93_EXTRA = new Set([V85_CLONE, V89_G_PRIEST, V89_G_SHARK]);
  function v93ResetArena(w, room) {
    let type = V93_ARENAS[room];
    if (!w || !type || !Array.isArray(w.mobs)) return false;
    let old = w.mobs.find((m) => m.type === type && !m.dead && m.hp > 0);
    // vedlejší postavy (klony, strážci) vždy pryč – boss je při prvním tahu znovu vytvoří
    w.mobs = w.mobs.filter((m) => !V93_EXTRA.has(m.type) && !m.fromBoss);
    if (old) {
      let x = Number.isFinite(old.homeX) ? old.homeX : old.x,
        y = Number.isFinite(old.homeY) ? old.homeY : old.y;
      if (x < 0 || y < 0 || x > W || y > H) {
        x = W / 2;
        y = H / 2;
      }
      let fresh = makeEnemy(type, x, y);
      fresh.homeX = x;
      fresh.homeY = y;
      w.mobs = w.mobs.map((m) => (m === old ? fresh : m));
    }
    w.total = w.mobs.length;
    w.kills = w.mobs.filter((m) => m.dead).length;
    if (room === current) v93ClearGlobals();
    return !!old;
  }
  function v93ClearGlobals() {
    if (typeof bossZones !== 'undefined') bossZones = bossZones.filter((z) => z.room !== current);
    V77.bubble = null;
    V81.stacks = 0;
    V81.fish = [];
    V81.wAcc = 0;
    V85.phase = null;
    V85.crowList = [];
    V85.crows = 1;
    V85.extra = 0;
    V89.shots = [];
    V91.until = 0;
    v91Set(false);
  }
  function enterRoomV95b(...args) {
    let from = current;
    // odchod z rozběhnuté arény: celý boj se resetuje (uloží se už čistý stav)
    if (world && V93_ARENAS[from] && args[0] !== from) v93ResetArena(world, from);
    let out = enterRoomV93b(...args);
    // příchod do arény (i ze staré uložené cache) – vždy čistý boj
    if (current !== from && V93_ARENAS[current]) v93ResetArena(world, current);
    return out;
  }
  function loadCharacterV111b(id) {
    let out = loadCharacterV93b(id);
    if (world && V93_ARENAS[current]) v93ResetArena(world, current);
    return out;
  }
  if (new URLSearchParams(location.search).has('test')) window.__v93 = { v93ResetArena, V93_ARENAS };


// ---- v95_robe.js ----
