    if (V95.wisps.length < 28 && Math.random() < 0.7)
      V95.wisps.push({ x: rnd(-18, 18), y: rnd(-6, 6), vy: rnd(-26, -12), vx: rnd(-8, 8), life: 0, max: rnd(0.9, 1.6), r: rnd(5, 9) });
    cx.save();
