    let t = sc.t,
      fade = clamp(t / 0.3, 0, 1) * clamp((sc.dur - t) / 0.4, 0, 1),
      ease = (x) => 1 - Math.pow(1 - clamp(x, 0, 1), 3),
      walk = ease((t - 0.4) / 1.4),
      dress = clamp((t - 2.0) / 0.6, 0, 1);
    cx.save();
    cx.globalAlpha = fade;
    cx.fillStyle = '#06030a';
    cx.fillRect(0, 0, W, H);
    let glow = cx.createRadialGradient(W / 2, 330, 10, W / 2, 330, 260);
    glow.addColorStop(0, 'rgba(140,20,30,' + (0.25 + dress * 0.35).toFixed(3) + ')');
    glow.addColorStop(1, 'rgba(0,0,0,0)');
    cx.fillStyle = glow;
    cx.fillRect(0, 0, W, H);
    // hrdina uprostřed
    let spec = { ...v38HeroSpec(), scale: 1 };
    if (dress >= 0.5) v95RobeSpec(spec);
    cx.save();
