    cx.scale(2.8, 2.8);
    v38PaintRig(cx, spec, { view: 'side', flip: 1, aim: -0.1, walk: 0, moving: 0, breath: Math.sin(t * 2) * 0.4, active: false, swing: 0 });
    cx.restore();
