  // Schopnost bosse (granát, vrána, hák, projektil…) zasáhne i během krátké nezranitelnosti
  // po předchozím úderu. Úskok, intro a oživení chrání dál.
  function v103Pierce(fn) {
    if (!player) return fn();
    let inv = player.invincible || 0,
      onlyHit = inv > time && player.v103Hit === inv;
    if (onlyHit) player.invincible = 0;
    try {
      return fn();
    } finally {
      if (onlyHit && (player.invincible || 0) < inv) player.invincible = inv;
    }
  }
  // aura róby kreslená za postavou (jemnější)
  function v38DrawBuffAuras(behind) {
    if (behind) v95DrawAura();
    let out = v38DrawBuffAurasV103b(behind);
    v38DrawBuffAurasV107(behind);
    return out;
  }
  function v103SetCount() {
    let n = 0;
    for (let k in equipped || {}) if (equipped[k]?.setId === 'bloodMoon') n++;
    return n;
  }
  function refreshUIV105b() {
    let out = refreshUIV103b();
    if (player) {
      if (equipped?.armor?.v95Robe && !player.v103Member) {
        player.v103Member = 1;
        checkAchievements(true);
      }
      let n = v103SetCount();
      if (n > (player.v103SetMax || 0)) {
        player.v103SetMax = n;
        checkAchievements(true);
      }
      if (player.v97MeiHome && !player.v103Mei) {
        player.v103Mei = 1;
        checkAchievements(true);
      }
    }
    return out;
  }
