// ---- v105_skills.js ----
  // ===================================================================
  // v105: Sura černá magie (Temná rána průrazná, Rána ducha zpomalí 40 %, delší Duch plamene
  //       a Temná ochrana), válečník – Silné tělo zvedá max. HP, použití předmětů z inventáře
  // ===================================================================
  function v105Is(cls, school, i, idx) {
    return player?.cls === cls && player.school === school && i === idx;
  }
  // Silné tělo: max. HP po dobu buffu (Lv1 100 → M1 500 → G1 1000 → P 2000), nedoléčuje
  function v105BodyHp() {
    let st = v99RankSteps(0);
    if (st >= 40) return 2000;
    if (st >= 30) return Math.round(1000 + (1000 * (st - 30)) / 10);
    if (st >= 20) return Math.round(500 + (500 * (st - 20)) / 10);
    return Math.round(100 + (400 * st) / 20);
  }
  function v105DarkPierce(q) {
    let t = spellRankTier(q);
    return t >= 3 ? Infinity : t === 2 ? 15 : t === 1 ? 5 : 1;
  }
  function skillNumbers(i) {
    let q = skillNumbersV105b(i);
    if (!q || !player) return q;
    if (player.cls === 'sura' && player.school === 'black' && (i === 1 || i === 3)) {
      q.buffDuration = Math.round((q.buffDuration || buffDuration(q)) * 1.15 * 10) / 10; // +15 %
    }
    if (v105Is('warrior', 'mental', i, 0)) q.v105Hp = v105BodyHp();
    return q;
  }
  function skillDetailsV107b(i) {
    let q = skillDetailsV105b(i);
    if (!q || !player) return q;
    if (v105Is('sura', 'black', i, 0)) {
      let n = v105DarkPierce(q);
      q.description = 'Vyšle tmavé kopí, které letí přes celou mapu. ' + (n === 1 ? 'Zasáhne první cíl (od M prorazí 5 cílů, od G 15, na P všechny).' : n === Infinity ? 'Proletí všemi nepřáteli v cestě.' : 'Prorazí až ' + n + ' cílů.');
      q.range = 'Neomezený dosah';
      q.effect = fmt(q.damage) + ' poškození · ' + (n === Infinity ? 'všechny cíle' : n + ' cíl' + (n === 1 ? '' : n < 5 ? 'e' : 'ů'));
    }
    if (v105Is('sura', 'black', i, 4)) {
      q.description = (q.description || '').replace(/\s*Zpomal[^.]*\./g, '') + ' Zpomalí cíl o 40 % na 3 s.';
      q.effect = fmt(q.damage) + ' poškození · zpomalení 40 %';
    }
    if (v105Is('warrior', 'mental', i, 0)) {
      q.description = 'Zpevní tělo: zvýší obranu a max. HP po dobu trvání (Lv1 +100 · M1 +500 · G1 +1 000 · P +2 000). Neléčí – zvedne jen maximum.';
      q.effect = (q.effect ? q.effect + ' · ' : '') + 'Max. HP +' + fmt(q.v105Hp || v105BodyHp());
    }
    return q;
  }
  function applySkillV109b(i, q, angle) {
    let start = projectiles.length,
      out = applySkillV105b(i, q, angle);
    if (!player || !q) return out;
    for (let p of projectiles.slice(start)) {
      if (p.owner !== 'player') continue;
      if (p.variant === 'darkBolt') {
        let n = v105DarkPierce(q);
        p.life = 6; // přes celou mapu (střela zmizí na okraji)
        p.range = 99999;
        if (n > 1) {
          p.remainingTargets = n === Infinity ? 9999 : n;
          p.damageFalloff = 1;
        }
      }
      if (p.variant === 'spiritShot') {
        p.slowOnHit = 0;
        p.v105Slow = true;
      }
    }
    if (v105Is('warrior', 'mental', i, 0)) {
      player.buffs.v105Body = time + (q.buffDuration || buffDuration(q));
      player.v105BodyHp = q.v105Hp || v105BodyHp();
      floatText(player.x, player.y - 70, 'Max. HP +' + fmt(player.v105BodyHp), '#ffcf6a', 16);
    }
    return out;
  }
  function hitV107b(m, damage, kind = 'basic') {
    let out = hitV105b(m, damage, kind);
    if (kind === 'spiritShot' && m && !m.dead && m.type !== 'stone' && player?.cls === 'sura') {
      m.v86Slow = Math.max(m.v86SlowUntil > time ? m.v86Slow || 0 : 0, 0.4);
      m.v86SlowUntil = time + 3;
    }
    return out;
  }
  function attributesV111b() {
    let a = attributesV105b();
    if (player && player.buffs?.v105Body > time) a.hp = (a.hp || 0) + (player.v105BodyHp || 0);
    return a;
  }
  // předměty z okna inventáře: hra je při otevřeném okně pozastavená – použití povolit
  function useSpecialV115b(key) {
    if (paused && backpackState && player && !isDead()) {
      paused = false;
      try {
        return useSpecialV105b(key);
      } finally {
        paused = true;
      }
    }
    return useSpecialV105b(key);
  }
  function refreshUIV109b() {
    let out = refreshUIV105b();
    if (player && player.v105BodyHp && !(player.buffs?.v105Body > time)) {
      player.v105BodyHp = 0;
      let mx = stats().maxHp;
      if (player.hp > mx) player.hp = mx;
    }
    return out;
  }
  if (new URLSearchParams(location.search).has('test')) window.__v105 = { v105BodyHp, v105DarkPierce };


// ---- v107_sura.js ----
  // ===================================================================
  // v107: Duch plamene podle stupně (M interval 0,5 s, G malé AoE, P dvě střely,
  //       výrazně lepší vizuál), sura s magickou zbraní +10 % poškození a čepel +10 %
  // ===================================================================
  function v107OrbitSteps() {
    return player?.cls === 'sura' && player.school === 'black' ? v99RankSteps(1) : 0;
  }
  // stupeň uložený při seslání (platí i pro sage kouzlo u jiného povolání)
  function v107BuffTier() {
    let t = player?.buffs?.orbitTier;
    return Number.isInteger(t) ? clamp(t, 0, 3) : v107OrbitTier();
  }
  function v107OrbitTier() {
    let st = v107OrbitSteps();
    return st >= 40 ? 3 : st >= 30 ? 2 : st >= 20 ? 1 : 0;
  }
  const V107_ORBIT = { interval: [0.9, 0.5, 0.5, 0.5], splashR: 42, splashMult: 0.5, cols: ['#d79771', '#ff7a2a', '#ff4a14', '#ffd27a'] };
  function v107OrbitTick() {
    if (!(player.buffs.orbit > time) || time < (player.buffs.orbitNext || 0)) return;
    let tier = v107BuffTier();
    player.buffs.orbitNext = time + V107_ORBIT.interval[tier];
    let list = allTargets()
      .filter((m) => d2(m, player) < 230)
      .sort((a, b) => d2(a, player) - d2(b, player));
    if (!list.length) return;
    let shots = tier >= 3 ? 2 : 1;
    for (let k = 0; k < shots; k++) {
      let m = list[k] || list[0],
        off = shots > 1 ? (k ? 1 : -1) * 0.12 : 0,
        sx = player.x + (shots > 1 ? (k ? 14 : -14) : 0);
      shoot(sx, player.y, Math.atan2(m.y - player.y, m.x - sx) + off * (list[k] ? 0 : 1), player.buffs.orbitDmg, 540, 270, V107_ORBIT.cols[tier], 'player', 0, 1.5 + tier * 0.25);
      let p = projectiles[projectiles.length - 1];
      Object.assign(p, { style: 'magic', skill: true, spellClass: 'sura', spellType: 'orbit', spellIndex: 1, v107Tier: tier });
      if (player.buffs.orbitSrc) p.v111 = player.buffs.orbitSrc; // Duch plamene ze sage kouzla
      if (tier >= 2) p.v107Splash = true;
      if (shots > 1 && !list[k]) p.homingId = m.id; // jediný cíl – obě střely do něj
    }
  }
  function skillProjectileImpactV111b(p, m) {
    if (p.v107Splash && p.owner === 'player' && m) {
      let R = V107_ORBIT.splashR;
      for (let o of allTargets()) if (o.id !== m.id && d2(o, m) < R + o.r) hit(o, p.dmg * V107_ORBIT.splashMult, 'orbit');
      effects.push({ type: 'v107Burst', x: m.x, y: m.y, r: R, life: 0.32, max: 0.32, gold: p.v107Tier >= 3 });
    }
    return skillProjectileImpactV107b(p, m);
  }
  // malý výbuch po zásahu (G a P)
  function v107DrawBursts() {
    for (let e of effects) {
      if (e.type !== 'v107Burst') continue;
      let k = 1 - e.life / e.max,
        r = e.r * (0.4 + 0.6 * k),
        a = 1 - k;
      cx.save();
      cx.globalCompositeOperation = 'screen';
      v38Glow(e.x, e.y, r * 1.3, e.gold ? '#ffd27a' : '#ff6a2a', 0.7 * a);
      v38Oval(cx, e.x, e.y + 4, r, r * 0.42, null, v38Rgba(e.gold ? '#fff0b0' : '#ffb070', 0.8 * a), 2);
      for (let j = 0; j < 6; j++) {
        let ang = j * 1.047 + e.x * 0.01,
          d = r * (0.5 + k * 0.6);
        v38Glow(e.x + Math.cos(ang) * d, e.y + Math.sin(ang) * d * 0.45 - k * 10, 4, '#ffcf7a', a);
      }
      cx.restore();
    }
  }
  // vizuál buffu podle stupně (vrací true = nakresleno)
  function v107PaintFlame(x, cy, y, behind) {
    if (!(player?.cls === 'sura' && player.school === 'black') && !Number.isInteger(player?.buffs?.orbitTier)) return false;
    let tier = v107BuffTier(),
      n = [3, 4, 5, 6][tier],
      rx = [30, 34, 38, 42][tier],
      ry = [12, 13, 14, 15][tier],
      sz = [0.45, 0.78, 0.95, 1.1][tier],
      spd = [1.9, 2.4, 2.8, 3.2][tier],
      pal = [
        ['#ff6a2a', '#ffd27a'],
        ['#ff4a14', '#ffb050'],
        ['#e8200c', '#ff9a3a'],
        ['#ff9a1a', '#fff2b0'],
      ][tier];
    cx.save();
    cx.globalCompositeOperation = 'screen';
    // kruh pod nohama (M+), runový kruh (G+), dvojitý zlatý (P)
    if (behind && tier >= 1) {
      let pulse = 0.75 + Math.sin(time * 4) * 0.25;
      v38Glow(x, y + 2, rx + 14, pal[0], (0.4 + tier * 0.1) * pulse, 0.4);
      v38Oval(cx, x, y + 2, rx + 2, (rx + 2) * 0.33, null, v38Rgba(pal[1], 0.55 * pulse), 1.6);
      if (tier >= 2) {
        for (let j = 0; j < 8; j++) {
          let a = time * 1.2 + (j * Math.PI) / 4;
          let gx = x + Math.cos(a) * (rx + 2),
            gy = y + 2 + Math.sin(a) * (rx + 2) * 0.33;
          v38Glow(gx, gy, 9, pal[0], 0.7);
          v38Flame(gx, gy + 2, 0.32, time * 1.5 + j, pal); // hořící kruh na zemi
        }
      }
      if (tier >= 3) v38Oval(cx, x, y + 2, rx + 12, (rx + 12) * 0.33, null, v38Rgba('#fff0b0', 0.5 * pulse), 1.2);
    }
    // obíhající plameny (vepředu / vzadu podle úhlu)
    for (let ring = 0; ring < (tier >= 2 ? 2 : 1); ring++) {
      let rr = ring ? rx * 0.62 : rx,
        dir = ring ? -1 : 1;
      for (let j = 0; j < n; j++) {
        let a = dir * time * spd + (j / n) * Math.PI * 2 + ring * 0.5,
          fx = x + Math.cos(a) * rr,
          fy = cy + 6 + Math.sin(a) * ry * (ring ? 0.7 : 1);
        if (behind !== Math.sin(a) < 0) continue;
        // ohon plamene (M+)
        if (tier >= 1)
          for (let t = 1; t <= 3; t++) {
            let b = a - dir * t * 0.16;
            v38Glow(x + Math.cos(b) * rr, cy + 6 + Math.sin(b) * ry * (ring ? 0.7 : 1), 9 - t * 2, pal[0], 0.35 - t * 0.08);
          }
        v38Glow(fx, fy, 14 + tier * 7, pal[0], 0.6 + tier * 0.12);
        v38Flame(fx, fy + 4, sz * (ring ? 0.7 : 1), time + j + ring, pal);
      }
    }
    // stoupající jiskry (G+) a zlaté jádro (P)
    if (!behind && tier >= 2) {
      for (let j = 0; j < 4 + tier * 2; j++) {
        let q = (time * 0.9 + j / (4 + tier * 2)) % 1,
          px = x + Math.sin(j * 2.7 + time) * (rx * 0.8);
        v38Glow(px, cy + 10 - q * 70, 3 + tier, pal[1], 1 - q);
      }
    }
    if (tier >= 3) v38Glow(x, cy, 46 + Math.sin(time * 5) * 4, '#ffcf6a', behind ? 0.22 : 0.12);
    cx.restore();
    return true;
  }
  function v38DrawBuffAurasV107(behind) {
    if (!behind) v107DrawBursts();
  }
  // ---------------- sura s magickou zbraní ----------------
  function v107WeaponSura() {
    let c = V111.swap ? V111.swap.saved : player; // vlastní povolání postavy, ne převzatého sage kouzla
    return c?.cls === 'sura' && c.school === 'weapon';
  }
  let v107HitDepth = 0;
  function hitV111b(m, damage, kind = 'basic') {
    // +10 % na veškeré poškození (jen na vnějším volání – vnitřní řetězec hit() už násobek nedostane)
    if (!v107HitDepth && v107WeaponSura() && Number.isFinite(damage) && damage > 0) damage *= 1.1;
    v107HitDepth++;
    try {
      return hitV107b(m, damage, kind);
    } finally {
      v107HitDepth--;
    }
  }
  function bladeBuffProfile(q) {
    let f = bladeBuffProfileV107b(q);
    if (player?.cls === 'sura') f.power = 1 + (f.power - 1) * 1.1; // čepel +10 % (50 % → 55 %)
    return f;
  }
  function skillDetailsV109b(i) {
    let q = skillDetailsV107b(i);
    if (!q || !player) return q;
    if (player.cls === 'sura' && player.school === 'black' && i === 1) {
      let t = v107OrbitTier();
      q.description =
        'Kolem tebe krouží plameny, které samy střílí na nejbližší nepřátele. M: střela každých 0,5 s (jinak 0,9 s) · G: malý výbuch po zásahu zasáhne i nepřátele vedle cíle · P: dvě střely naráz.';
      q.effect = (q.effect || '').replace(/\s*·?\s*0,9 s interval/, '') + ' · ' + ['interval 0,9 s', 'interval 0,5 s', 'interval 0,5 s + výbuch', '2 střely · 0,5 s + výbuch'][t];
    }
    return q;
  }
  if (new URLSearchParams(location.search).has('test')) window.__v107 = { v107OrbitTier, V107_ORBIT };


// ---- v109_perf.js ----
  // ===================================================================
  // v109: Šaman léčení – Ošetřit ve stunu (M ruší stun, P všechny negativní efekty),
  //       Útok+ = polovina % aury + zkrácení obnovy; výkon: UI se obnovuje jednou za snímek,
