      wrap = document.createElement('div');
    wrap.className = 'v111-menu';
    for (let i of list) {
      let q = skillDetails(i);
      wrap.appendChild(v111Card(esc(q.name) + ' · P1', esc(v111SchoolLabel(player.cls, player.school)), '', () => v111ConfirmSacrifice(i)));
    }
