    cx.moveTo(x - 50, y);
    cx.lineTo(x - 50, y - 70);
    cx.quadraticCurveTo(x, y - 128, x + 50, y - 70);
    cx.lineTo(x + 50, y);
    cx.closePath();
    cx.clip();
    let g = cx.createRadialGradient(x, y - 50, 4, x, y - 50, 90);
