        cx.fillRect(px - 12, 0, 24, 104);
        cx.fillStyle = '#5a2e24';
        cx.fillRect(px - 16, 96, 32, 10);
        // prapor
        cx.fillStyle = '#7a1210';
        cx.beginPath();
        cx.moveTo(px - 10, 8);
        cx.lineTo(px + 10, 8);
        cx.lineTo(px + 10, 62);
        cx.lineTo(px, 54);
        cx.lineTo(px - 10, 62);
        cx.closePath();
