        bossCast(m, 'wolfCharge', rage ? 0.85 : 1.0, { origin: { x: m.x, y: m.y }, end, angle, width: 34, remaining: 1, col: '#7ad0ff', v117: 'spear', label: 'Hromové kopí' });
